sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float scale;
uniform float phase;
uniform float radius;
uniform float feather;
layout(color) uniform half4 color1;
layout(color) uniform half4 color2;
uniform float density;
uniform float2 offset;
uniform float fill;
uniform float alpha;
uniform float blend;
uniform float seed;
uniform float slack;
float hash12(float2 p) {
    float3 q = fract(float3(p.xyx) * 0.1031);
    q += dot(q, q.yzx + 33.33);
    return fract((q.x + q.y) * q.z);
}
float2 hash22(float2 p) {
    float3 q = fract(float3(p.xyx) * float3(0.1031, 0.1030, 0.0973));
    q += dot(q, q.yzx + 33.33);
    return fract((q.xx + q.yz) * q.zy);
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    float cell = size.y * max(scale, 0.01) / 13.0;
    float2 x = (coord - size * 0.5 - offset) / cell;
    float2 n = floor(x);
    float cover = 0.0;
    float3 dot_ = float3(0.0);
    float r = max(radius, 0.0) * 0.5;
    float soft = max(feather * r, 0.5 / cell);
    for (int j = -1; j <= 1; j++) {
        for (int i = -1; i <= 1; i++) {
            float2 g = n + float2(float(i), float(j));
            for (int k = 0; k < 3; k++) {
                float2 h = hash22(g + seed * 9.7 + float(k) * 41.3);
                float chance = k == 0 ? density / 11.0 : density - 10.0 - float(k);
                if (hash12(g * 1.7 + float(k) * 13.1 + seed) >= chance) continue;
                float t = 6.2831853 * (phase * (0.6 + 0.8 * h.y) + h.x);
                float2 at = g + 0.5 + (h - 0.5) * slack * 0.6 + 0.2 * slack * float2(cos(t), sin(t));
                float d = length(x - at);
                float c = 1.0 - smoothstep(r - soft, r + soft, d);
                if (c > cover) {
                    cover = c;
                    dot_ = mix(float3(color1.rgb), float3(color2.rgb), hash12(g * 3.1 + float(k) * 5.3 + seed * 2.1));
                }
            }
        }
    }
    float a = float(src.a);
    float3 base = float3(src.rgb) / a;
    float3 shade = blend < 0.5 ? dot_ : blend < 1.5 ? base * dot_ : base + dot_ - base * dot_;
    float k = cover * clamp(alpha, 0.0, 1.0);
    float layerA = clamp(fill, 0.0, 1.0);
    float outA = k + layerA * (1.0 - k);
    float3 rgb = outA > 0.0 ? (shade * k + base * layerA * (1.0 - k)) / outA : float3(0.0);
    return half4(half3(rgb) * half(outA * a), half(outA * a));
}
